import type { FastApiPaths } from "../layout.js";

/**
 * Alembic, wired so `alembic upgrade head` works on a fresh clone.
 *
 * The initial migration is written out rather than left to be autogenerated: a
 * scaffold whose first command is "now generate the migration yourself" is not a
 * working project. The URL is never written into alembic.ini - env.py reads it
 * from settings, so there is one source of truth and no credentials in a config file.
 */

export function alembicIni(): string {
  return `[alembic]
script_location = migrations
# So "app" is importable when env.py runs from the project root.
prepend_sys_path = .
# Deliberately empty: env.py sets the URL from app settings (and therefore from the
# environment), which keeps credentials out of this file.
sqlalchemy.url =

[loggers]
keys = root,sqlalchemy,alembic

[handlers]
keys = console

[formatters]
keys = generic

[logger_root]
level = WARNING
handlers = console
qualname =

[logger_sqlalchemy]
level = WARNING
handlers =
qualname = sqlalchemy.engine

[logger_alembic]
level = INFO
handlers =
qualname = alembic

[handler_console]
class = StreamHandler
args = (sys.stderr,)
level = NOTSET
formatter = generic

[formatter_generic]
format = %(levelname)-5.5s [%(name)s] %(message)s
datefmt = %H:%M:%S
`;
}

export function alembicEnvPy(paths: FastApiPaths): string {
  return `from logging.config import fileConfig

from alembic import context
from sqlalchemy import engine_from_config, pool

from ${paths.baseMod} import Base
from ${paths.configMod} import settings

# Importing the models is what populates Base.metadata - without it autogenerate
# would cheerfully produce a migration that drops every table.
from ${paths.modelMod} import Item  # noqa: F401

config = context.config
config.set_main_option("sqlalchemy.url", settings.database_url)

if config.config_file_name is not None:
    fileConfig(config.config_file_name)

target_metadata = Base.metadata


def run_migrations_offline() -> None:
    """Emit SQL to stdout instead of running it (alembic upgrade head --sql)."""
    context.configure(
        url=settings.database_url,
        target_metadata=target_metadata,
        literal_binds=True,
        dialect_opts={"paramstyle": "named"},
        compare_type=True,
    )
    with context.begin_transaction():
        context.run_migrations()


def run_migrations_online() -> None:
    connectable = engine_from_config(
        config.get_section(config.config_ini_section, {}),
        prefix="sqlalchemy.",
        poolclass=pool.NullPool,
    )
    with connectable.connect() as connection:
        context.configure(
            connection=connection,
            target_metadata=target_metadata,
            # Catches a changed column type, which Alembic ignores by default.
            compare_type=True,
            # SQLite cannot ALTER a column, so Alembic rebuilds the table instead.
            render_as_batch=True,
        )
        with context.begin_transaction():
            context.run_migrations()


if context.is_offline_mode():
    run_migrations_offline()
else:
    run_migrations_online()
`;
}

export function alembicScriptMako(): string {
  return `"""\${message}

Revision ID: \${up_revision}
Revises: \${down_revision | comma,n}
Create Date: \${create_date}

"""
from collections.abc import Sequence

from alembic import op
import sqlalchemy as sa
\${imports if imports else ""}

revision: str = \${repr(up_revision)}
down_revision: str | None = \${repr(down_revision)}
branch_labels: str | Sequence[str] | None = \${repr(branch_labels)}
depends_on: str | Sequence[str] | None = \${repr(depends_on)}


def upgrade() -> None:
    \${upgrades if upgrades else "pass"}


def downgrade() -> None:
    \${downgrades if downgrades else "pass"}
`;
}

/** The first migration, matching the Item model exactly so `upgrade head` works immediately. */
export function initialMigrationPy(): string {
  return `"""create items table

Revision ID: 0001_create_items
Revises:
Create Date: generated by agbar

Written by hand to match the initial model. Every change after this one should be
generated: alembic revision --autogenerate -m "what changed", then read the result
before applying it - autogenerate is a draft, not an authority.
"""
from collections.abc import Sequence

import sqlalchemy as sa
from alembic import op

revision: str = "0001_create_items"
down_revision: str | None = None
branch_labels: str | Sequence[str] | None = None
depends_on: str | Sequence[str] | None = None


def upgrade() -> None:
    op.create_table(
        "items",
        sa.Column("id", sa.Integer(), primary_key=True, nullable=False),
        sa.Column("name", sa.String(length=200), nullable=False),
        sa.Column("description", sa.String(length=1000), nullable=True),
        sa.Column("created_at", sa.DateTime(timezone=True), server_default=sa.func.now(), nullable=False),
    )
    op.create_index("ix_items_name", "items", ["name"])


def downgrade() -> None:
    """Reversible on purpose: a migration you cannot roll back is a one-way door."""
    op.drop_index("ix_items_name", table_name="items")
    op.drop_table("items")
`;
}
